#!/usr/bin/env bash
# FlowForge: POST /auth/register. Run from the repo root:  bash auth-register.sh
# NEW files are skipped if they exist. FILES MARKED "force" ARE OVERWRITTEN
# (they are the stubs generated by `nest g`). Commit first so `git diff` is your safety net.
set -e

write() {            # create only if missing
  if [ -e "$1" ]; then
    echo "skip      $1 (already exists)"
    cat > /dev/null
  else
    mkdir -p "$(dirname "$1")"
    cat > "$1"
    echo "create    $1"
  fi
}

write_force() {      # create or overwrite
  mkdir -p "$(dirname "$1")"
  if [ -e "$1" ]; then echo "overwrite $1"; else echo "create    $1"; fi
  cat > "$1"
}

# ---------- Shared schema (used by API now, web later) ----------

write_force packages/shared/src/index.ts <<'EOF'
import { z } from 'zod';

export const Role = z.enum(['OWNER', 'EDITOR', 'VIEWER']);
export type Role = z.infer<typeof Role>;

export const registerSchema = z.object({
  email: z.string().trim().email(),
  password: z.string().min(8).max(128),
  name: z.string().trim().min(1).max(100),
});
export type RegisterInput = z.infer<typeof registerSchema>;

export const loginSchema = z.object({
  email: z.string().trim().email(),
  password: z.string().min(1),
});
export type LoginInput = z.infer<typeof loginSchema>;
EOF

